  _ = `Start typing to get a filtered list of your packages.`,
  _ = `Note that these are not AppIDs. These are store packages that sell your product on the Steam store.`,
  _ = `Enter package name or id here`,
  _ = `Select one or more packages below and click 'Continue' to add them to this bundle.`,
  _ = `Bundle Collaboration`,
  _ = `Optional: You can choose to invite other developers to include their games into your bundle. As the owner of the bundle, you are responsible for coordinating with the other developers. Also, as the owner, you are the only one able to publish the bundle to the Steam store. The invited parties get to choose which games/packages to include. Each time a package is added to the bundle or the discount percentage change, then all collaborators must approve their game for inclusion into the bundle before it can be published.`,
