  _ = `There are no visibility limitation caused by game pricing or current discount. `,
  _ = `You may need to adjust your game pricing in certain currencies or the level of discount applied to this bundle.`,
  _ = `Do you want to discard unsaved changes?`,
  _ = `Sale Pages Dashboard`,
  _ = `Sale Promotion Event Pages`,
  _ = `Here you will find the sale pages on Steam that feature one or more games that you have management rights to. In some cases these pages are organized by event organizers and sometimes by Valve as part of organized promotional events.`,
  _ = `These are all of the active and staged sale pages created by either Valve or an approved external party. To setup a new partner to be able to create their own sale page %1$s. You can forward to your partner %2$s.`,
  _ = `please read this guide`,
  _ = `the external facing documentation on this feature`,
  _ = `Summary Stats`,
  _ = `Active Sales: %1$s`,
  _ = `Upcoming Seasonal Sale Featured Pages: %1$s`,
  _ = `These are sale pages that are planned to be featured on the homepage of Steam during the next major seasonal sale (assuming the included games will be on discount). Please check to make sure these include all the relevant titles in your franchise.`,
