  _ = `Browse`,
  _ = `This event is hidden and you do not have edit access. But someone on your team does. To determine the person on your team with permission to edit this event, hover over the group icon below and click 'See members list'. By default, the members with 'officer' status in the group have edits rights on this event.`,
  _ = `This event is not yet visible but we're showing this to you because you have a game that has been listed on the sale page. If this is unexpected, please contact the sale organizers.`,
