  _ = `Prune Game`,
  _ = `UnPrune Game`,
  _ = `Invite Game`,
  _ = `Invite All Gamed`,
  _ = `Prune All Games`,
  _ = `Failed To Update, check console for details`,
  _ = `Invite All Pending Review Apps`,
  _ = `Prune All Pending Review Apps`,
  _ = `Move pending review apps into the new state. This action is NOT reversible. Click OK to start.`,
  _ = `Batch updates are now completed, you can close the dialog`,
  _ = `Partner's appeal:`,
  _ = `Appeals Creation Time:`,
  _ = `Accept Appeal`,
  _ = `Deny Appeal`,
  _ = `Are you sure? This will update the state for (%1$s) and notify the appeals requester via email about our decisions.`,
  _ = `The event page will have one or more sections that only permit games with discounts to appear. There will also be one or more sections on the event page that prioritize featuring games with discounts.`,
  _ = `Registration for %1$s`,
  _ = `Status: Not eligible for participation`,
  _ = `Status: No longer eligible because the game has released`,
  _ = `Status: Not eligible because mods can't take part in Steam Next Fest`,
  _ = `Status: Not reviewed for participation`,
  _ = `Status: Your appeal to register is awaiting review`,
  _ = `The requested (%1$s) OptIn doesn't exist.`,
  _ = `OptIn Event is Over.  No appeals are possible at this point in time.`,
  _ = `The game (%1$s) is already part of the event (%2$s).`,
  _ = `Go to the Registration Page here.`,
  _ = `Our review team determined that %1$s does not meet the eligibility criteria for this event`,
  _ = `Games invited to participate in each of the official Steam themed sales must clearly fit within the overall theme and eligibility criteria for the event. Eligibility is determined by the tags applied to your game’s store page, as well as the gameplay that is evident from how you describe and represent your game on your store page.`,
  _ = `When building a list of games to invite, we typically look for games that match the following:`,
  _ = `<2>Critical store tags</2> that represent the theme. You can review the tags currently set for your game by visiting the <1>tagging wizard</1>.`,
  _ = `<1>Store page description</1> we look at the trailer, screenshots, and description of the game to see whether it is described in a way that falls within the theme of the event.`,
  _ = `Our review team did not originally consider %1$s for this event`,
  _ = `Eligibility Criteria`,
  _ = `Appeal for %1$s to be included`,
  _ = `Appeal for %1$s have been closed`,
  _ = `Request a review for %1$s`,
  _ = `If you believe your game clearly matches all the eligibility criteria above, you can use the appeals process here to let us know. We will review your title based on its store page, so please review your store page—including trailers, screenshots, and tags—to make sure your title is presented in a way that is clearly within the theme at hand.`,
  _ = `After review, we do not think %1$s fits the theme of this event. Please be on the lookout for future events that better align with the theme and/or gameplay of your title.`,
  _ = `Begin appeal process`,
  _ = `Your appeal has been submitted`,
  _ = `Your appeal has been submitted. These requests are reviewed on a regular cadence, and we will email you with the results of your appeal.`,
  _ = `The appeal process`,
  _ = `These requests are reviewed on a regular cadence up to and throughout %1$s. We will email you with the results of your appeal.`,
  _ = `Appeal Results: Declined`,
  _ = `Our team took a second look at your game and determined that it is not a good fit for %1$s.`,
  _ = `There are special event opportunities all year long, so please take a look at the list of <1>upcoming events</1> or keep your eye out for an event with a theme that is a better fit for your game.`,
  _ = `For more details, please see the %1$s`,
  _ = `%1$s documentation`,
  _ = `For general information about Steam themed sale events, including detail on selection and invitation process, ways to participate, event visibility and promotion, in-event game visibility, and marketing materials permissions, please visit the <1>Steam Themed Sale Events parent documentation</1>.`,
  _ = `Need Help?`,
  _ = `If you believe your game completely matches the eligibility criteria for this event, you can use the appeals process here to let us know.`,
  _ = `Please review your <1>store page</1> and <2>tags</2> with the eligibility criteria in mind – we will not accept supplemental information like gameplay clips, demos, or presentations. Only information available to all customers will be used in this review process.`,
  _ = `Tell Us More About Your Game`,
  _ = `Please use the form below to describe what we might have missed when reviewing your game’s store page.`,
  _ = `Submit Appeal`,
  _ = `Error occurred saving change. Please try again later.`,
  _ = `Appeal not possible`,
  _ = `Your game's release date is set to be prior to this event. Only games releasing after %1$s are eligible to participate.`,
  _ = `If your release plans have changed and you'll be releasing after this date, please update the release date for your game in Steamworks.`,
  _ = `For more details, please see <1>Release Dates Documentation</1>.`,
  _ = `Your game is in a released state. We do not accept released games into this event.`,
  _ = `The Event has already started. We are no longer accepting appeals for inclusion.`,
  _ = `Why wasn't your game included?`,
  _ = `%1$s has been removed from %2$s`,
  _ = `%2$s is for games that have not yet released. %1$s is now available on Steam, so it no longer meets the eligibility requirements and has been removed from the event. No action is needed on your part.`,
  _ = `The game was removed on %1$s.`,
  _ = `Steam Next Fest doesn't include mods. %1$s is a mod on Steam, so it has been removed from %2$s. No action is needed on your part.`,
  _ = `The release date of your game is set in the past, which is why your game wasn't automatically eligible. If your release date is set to a past date, but you still haven't released, you may appeal to be included by clicking the button below.`,
  _ = `Next Fest Registration Question and Answers`,
  _ = `Next Fest Question and Answers`,
  _ = `Survey: %1$s`,
  _ = `Game: %1$s`,
  _ = `Thank you for participating in %1$s!`,
  _ = `This quick survey will help us understand your experience with this event and help us to improve the way we run future events on Steam.`,
  _ = `Invalid Survey`,
  _ = `Submit Survey Answers`,
  _ = `Submit my survey answers to Steam?`,
  _ = `Thank you, survey submitted.`,
  _ = `Sorry, error submitting survey, please try again later.`,
  _ = `How satisfied were you with the communication from Valve about Next Fest?`,
  _ = `<1>Excellent</1> I totally understood the process and deadlines`,
  _ = `<1>It was fine</1> I mostly understood what to do and when the deadlines were`,
  _ = `<1>Unsatisfied</1> I found the process unclear or confusing`,
  _ = `Could you describe what part you found to be unclear or confusing?`,
  _ = `How many full-time people do you have working on your game?`,
  _ = `<1>0</1> One or more, but only working part-time on the game`,
  _ = `<1>1</1> Just me, full time`,
  _ = `<1>2-10</1> A small team`,
  _ = `<1>11+</1> A pretty good size team`,
  _ = `Did your participation in Next Fest meet your expectations?`,
  _ = `<1>Yes</1> I got what I was hoping for`,
  _ = `<1>No</1> I was expecting more from the event`,
  _ = `Where did Next Fest come up short for you?`,
  _ = `Did you change your release plans as a result of participating in Next Fest?`,
  _ = `<1>No</1> We're on track and forging ahead as previously planned!`,
  _ = `<1>Yes</1> We've changed our release date or scope of the game as a result of Next Fest`,
  _ = `What changes did you make to your plans? Why?`,
  _ = `Do you have any feedback or suggestions?`,
  _ = `What can we do to make Next Fest better?`,
  _ = `Build %1$s is now live for players on the branch "%2$s"`,
  _ = `Now, tell players about your changes`,
  _ = `Players that have your game installed will see a download queued for this update. They'll probably want to know what changed.`,
  _ = `Use the form to the right to post as a small update or open the full editor to post your change notes as a regular or major update.`,
