  _ = `This invitation was cancelled`,
  _ = `How do invites work?`,
  _ = `If your game is invited to participate in a Daily Deal, you'll recieve an email and see your game listed above. Here's how the process works from that point:`,
  _ = `Select an available date within the next 6 months that works for you.`,
  _ = `The visibility on the Steam homepage and applicable tag pages runs for 24 hours, while the discount will be active for between 7 and 14 days depending on the discount length you selected.  It will start at 10am Pacific time on your selected date.`,
  _ = `When you select an available date, it will prompt you to enter a discount percentage and select which packages you wish to include in the promotion.`,
  _ = `We ask that you pick a discount % that is at least as good as the best discount you have run in the past, if not better.`,
  _ = `If you are not ready to schedule your Daily Deal right now, the invite will be on your Daily Deal Dashboard.  Please keep the expiration date in mind.`,
  _ = `If you need to change your date, cancel or have questions - %1$s`,
  _ = `Contact us here`,
  _ = `Daily Deal Best Practices`,
  _ = `We find it often beneficial to time your increased visibility and discount with other activities you might have planned, such as a game content update, livestream, or community event.`,
  _ = `If you have other scheduled discounts planned within a month of your selected Daily Deal, please try to keep the discount percentage equal among those discounts. When we feature you game as a Daily Deal, we like it to be as good as or better than offers you've run before.`,
