  _ = `The base price of this package in one or more currency is below the minimum allowed. As such, this package will not be purchasable in those countries or any others where this discount causes the end price to fall below the requirement minimums. To ensure this package can be purchased everywhere, please update pricing for this package to at least the Steam minimum.`,
