  _ = `To help you manage your pricing across the 35+ currencies that Steam supports, this tool offers a method of conversion for how to translate your base USD price into region appropriate levels. This conversion is based on a combination of currency value, regional purchasing power, required taxes, and our own experience selling in particular regions.`,
