  _ = `Spotlight Capsules (%1$s)`,
  _ = `Usage: Spotlight Capsules appear near the top of the Steam home page and relevant Store hubs for specific promotions such as Midweek Deals or Weekend Deals.`,
  _ = `Design: Spotlight Banner will automatically have a section rendered over the bottom with the text describing the type of promotion (eg, 'Weekend Deal') and the end dates of the promotion.`,
  _ = `The amount of the bottom of the image that may be covered can vary depending on the volume of text and/or language.`,
  _ = `Please refrain from putting key elements in the bottom 1/4 of the image.`,
  _ = `Otherwise, this capsule should mostly just focus on your game art and logo.`,
  _ = `Usage: Spotlight vertical capsules appear on the home page under the "Discounts & Events" section. This asset is only required for Franchise and Publisher sale events. Spotlights referencing a single game will use that game's Store Vertical Capsule automatically.`,
  _ = `Design: Spotlight Capsules are the same size as a game's vertical capsules.`,
  _ = `The Spotlight Capsule should include your game art and logos only`,
  _ = `No additional text should be included (eg. "Publisher Sale", "Free Weekend", "Up to 90% off"). The localized banner overlayed on the top of this asset will contain context. The only exception is "Franchise Sale" text.`,
  _ = `For clarity, text like "Franchise Sale", "Publisher Sale", "Free Weekend", should not be included`,
  _ = `Reserve space on the top portion of the art for a spotlight banner to be overlayed on the capsule.`,
  _ = `Pop-up Marketing Message (%1$s)`,
  _ = `Usage: Steam pop-up window and on the front page of Steam`,
  _ = `Design: For best results, please make sure the logo is clearly legible, and include a callout to the type of promotion it is (Pre-Purchase, Now Available, Coming Soon, etc...).`,
  _ = `Price and call-to-action button will automatically appear below the image.`,
  _ = `Keep file size below 5MB, .jpg, .gif, .png`,
  _ = `Marketing Messages support animation, which should always be fairly subtle. If you explore this route, you must read our documentation linked above and adhere to our animation specifications.`,
  _ = `Pop-up Update Marketing Message (%1$s)`,
  _ = `Usage: In the Steam pop-up window to communicate that this game has released a major update`,
  _ = `Design: Should include only two elements – art and game logo`,
  _ = `Art: For best results, use art that represents the new content from the update such as new key art, screenshots, or new characters and features, etc.`,
  _ = `Logo: Can be the main game title logo, or an official logo of the game update if applicable. If there are multiple language versions of the logo for localized assets, please provide.`,
  _ = `Do not include any additional text in this image. Information about the event update and call-to-action will automatically appear alongside the image.`,
  _ = `Static image only, not animated.`,
  _ = `Final upload format: JPEG, PNG, or GIF. File size < 5MB`,
  _ = `Please always provide layered PSD files`,
  _ = `Takeover Asset (%1$s)`,
  _ = `Hub Takeover Asset (%1$s)`,
  _ = `Usage: Artwork that appears at the very top of the Steam Front page and/or Store hub and is a very large treatment for everyone to see.`,
  _ = `Requires two formats, large and mobile. For the preview here, you will only upload static versions of your takeover, even if you are creating animated versions too.`,
  _ = `Keep file size below 5MB, .jpg, .gif, .png`,
  _ = `This may use feathered edges or may transition to a different solid color if the primary color contrasts too greatly with the standard blue color of the Steam store.`,
  _ = `Critical content should be placed within the center 940px of the image.`,
  _ = `Takeovers support animation, which should always be fairly subtle. If you explore this route, you must read our documentation linked above and adhere to our animation specifications.`,
  _ = `Takeunder Banner Asset (%1$s)`,
  _ = `Usage: Artwork that appears at below the special offers section on Front page and/or Store hubs.`,
  _ = `Requires two formats, large and mobile. Make sure there is a clear call-to-action and the dates of the event.`,
  _ = `Keep file size below 5MB, .jpg, .gif, .png`,
  _ = `Sale Page Assets (%1$s)`,
  _ = `Within sale pages, there are multiple asset types to be considered`,
  _ = `Sale Background Image`,
  _ = `Usage: this artwork appears in the background of your sale page`,
  _ = `Design: The left/right/bottom edges should fade or transition to a single solid color that is applied to the rest of your page. Please double-check the template for details. If you are not using a sale page logo, then this image should include your event logo and dates well within the safe area at the top of the image.`,
  _ = `This image should be static and below 5MB, .jpg, .png`,
  _ = `Sale Page Logo`,
  _ = `Usage: this image appears at the top of your sale page, in front of your background image.`,
  _ = `Design: This image should include your event logo and dates on a transparent background.`,
  _ = `Event Cover / Preview`,
  _ = `Usage: this artwork is used to represent your event in the Steam News Hub, on the Special Offers Page, and will appear as the preview when people share your event URL on social media`,
  _ = `Design: This image should include your event logo and dates`,
  _ = `Event Header`,
  _ = `Usage: This artwork is displayed at the top of the announcement that is associated with your sale page.`,
  _ = `Design: This image is not critical; it's simply intended to add some context and color for your written announcement.`,
  _ = `This image should be static and below 5MB, .jpg, .png`,
  _ = `Store Page Banner`,
  _ = `Usage: This banner appears on the top of each game that is included in your event. For that reason, you need to have permission from the creators of every included game or you cannot use this feature.`,
  _ = `Design: This image should include your event logo and dates and ideally include a call to action or brief tagline for your event so that players understand the context.`,
  _ = `This image should be static and below 5MB, .jpg, .png`,
  _ = `Store Page Banner, Mobile`,
  _ = `Usage: is the mobile version of the Store Page Banner. It replaces the default Store Page Banner on screens 500px or narrower.`,
  _ = `This image should pretty closely match the contents of your default Store Page Banner`,
  _ = `This image should be static and below 5MB, .jpg, .png`,
