  _ = `Each asset must be under 5MB`,
  _ = `Artwork must be in layered Photoshop (PSD) files`,
  _ = `Main game/character art in highest resolution possible (smart object preferred). Doing so allows us to re-use these assets to create other Steam promotional art when necessary.`,
  _ = `Logo (smart object preferred) separated from the art.`,
  _ = `Any text should be editable in a separate “text” folder within the PSD document, so that it may be easily localized by our team.`,
  _ = `Include any fonts used (especially custom fonts).`,
  _ = `Please keep all text styling and layers within Photoshop. Do not link to files from other programs, such as Illustrator.`,
  _ = `For animated assets, please also provide a seamless looping MP4 or PNG sequence without the text and logo. Make sure that any text is on a separate layer and not animated so it may be easily localized by our team.`,
