  _ = `Publish Project`,
  _ = `This will create an established version of this project and create the tables necessary for snapshotting. Changing the data sources used will require re-publishing.`,
  _ = `Copy another Published Version`,
  _ = `This will copy all the settings of the selected published project over this unpublished project.  Are you sure?`,
