  _ = `Snapshot Location`,
  _ = `What kind of storage to use for snapshot data`,
  _ = `SQL`,
  _ = `MinIO`,
  _ = `Both`,
  _ = `Sample Percent`,
  _ = `The percentage of the snapshots that we will sample to train on. <1><2>Less than 100 will randomly exclude some samples</2><2>More than 100 will cause us to oversample (only useful if your sampling has randomness, for example when using something like a conditional extract)</2></1>`,
  _ = `Snapshot Type`,
  _ = `How this project does snapshotting:<1><2>Manual - only snapshots on calls to SnapshotProject</2><2>Auto (Accounts) - Scheduled job that runs over all account ids, snapshotting at each</2><2>Auto (AppIDs) - Schedule job that runs over all AppIDs, snapshotting at each</2><2>Other Project - Uses another project's snaphsots</2></1>`,
  _ = `Manual`,
  _ = `Automatic - Accounts`,
  _ = `Automatic - AppIDs`,
  _ = `Automatic - ForumSpam`,
  _ = `Automatic - GameReview (Labeled)`,
