  _ = `Activity`,
  _ = `Wishlists`,
  _ = `Wishlists (last 3 months)`,
  _ = `Snapshot Percentage`,
  _ = `Activity recency in days`,
  _ = `Release recency in months`,
  _ = `Project ID`,
  _ = `Published Version`,
  _ = `Snapshot Schedule`,
  _ = `How often and when the specified auto-snapshot should run.`,
  _ = `Snapshot Jobs`,
  _ = `How many jobs to use when snapshotting -- using more increases load on the mllearn servers, but can complete the job more quickly (up to a point, where we start hitting sql contention)`,
  _ = `Histogram Normalization`,
  _ = `There are times where you want to make sure that the number of training samples are similar for a particular data source element.  If that's the case, you can use a histogram filter, specifying a particular data source field a range, along with the number of buckets within that rate.  When sampling datasources for the training set, it will ensure that the same number of samples are taken from each bucket.  When choosing values, be aware that the sample count of all buckets is restricted by the smallest number of samples in any bucket, which can significantly reduce the size of your training set.`,
  _ = `Data Element`,
  _ = `None`,
  _ = `Minimum value`,
  _ = `Maximum value`,
  _ = `Number of histogram buckets`,
  _ = `Range Filter`,
  _ = `Filter out snapshots that don't have the specified data element in the specified range`,
  _ = `Data Element`,
  _ = `None`,
  _ = `Minimum value`,
  _ = `Maximum value`,
  _ = `Exclusion Filters`,
  _ = `Exclude samples by comparing their data files against comparison values. Exclusions are cumulative, so any of these filters being true will exclude the sample. Exclusion filters happen before inclusion filters, and any sample that has been excluded cannot be included.`,
  _ = `Inclusion Filters`,
  _ = `Inclusion samples by comparing their data files against comparison values. Inclusions are cumulative, so any of these filters being true will include the sample, so long as it hasn't been excluded by the exclude filters.`,
  _ = `Add Filter`,
  _ = `Remove Filter`,
  _ = `Fetch Workers`,
  _ = `The number of workers that are used to fetch data. Wants to be set high enough such that it's fast but not overloading SQL, 64 workers is generally a good balance.`,
  _ = `Snapshots Location`,
  _ = `Where to pull snapshots from during training fetch.`,
  _ = `Number of fetch workers`,
  _ = `Fetch Chunk Rows`,
  _ = `The number of rows in the numpy files that the fetch step creates. Larger files are more efficient to load and process, but can result in a less-well-distributed shuffle. Generally should be no larger than 1% of your total number of snapshots.`,
  _ = `Number rows in fetch chunk`,
  _ = `Train Batch Size`,
  _ = `The batch size to use when training the model. Larger batch sizes are more efficient to train, but may resolve less quickly. 2000 is a reasonable size for large projects.`,
  _ = `Batch size`,
  _ = `Optimizer`,
  _ = `Different optimizers have different characteristics and may be better or worse in different projects:<1><2>Adam - A high-quality modern optimizer that includes both momentum and smart learning rate annealing</2><2>AdaDelta - A more robust variant of Adagrad</2><2>AdaGrad - A broadly useful optmizer</2><2>SGD - A simple and classic optmizer, useful for shallow neworks</2></1>`,
  _ = `Learning Rate`,
  _ = `The Learning Rate to use for the specified optimizer.  Setting to 0 will use the default.  Also can specify a number of warmup steps and the initial learning rate for warmup, along with the number of learning rate decay steps and the exponential decay rate.`,
  _ = `Warmup Steps`,
  _ = `Warmup Start`,
  _ = `Decay Steps`,
  _ = `Decay Rate`,
  _ = `Weight Decay`,
  _ = `The Weight Decay value to use for the specified optimizer.  Setting to 0 will use the default.`,
  _ = `Clip Norm`,
  _ = `The Clip Norm value to use for the specified optimizer.  Setting to 0 will use the default.`,
  _ = `Class Weights`,
  _ = `Sample label class weights and weight training to help with unbalanced datasets?`,
  _ = `Epoch Count`,
  _ = `The maximum number of epochs to train your model. Small datasets tend to require more epochs (up to 100) but larger datasets often need fewer, sometimes just a few.`,
  _ = `Maximum number of Epochs to train for`,
  _ = `Loss Improvement Threshold`,
  _ = `The threshold at which we determine that an epoch's loss has not improved enough to be considered worthwhile.  Any epoch whose loss improves by less than this value is considered "not good enough".`,
  _ = `No Improvement Epoch Limit`,
  _ = `Epochs`,
  _ = `How many epochs that are below the loss improvement threshold before we end the train.`,
  _ = `Threshold`,
  _ = `Profile`,
  _ = `You can specify certain batches in a given epoch to log profiling data, generally 10 or so batches is sufficient.  Setting to Epoch 0 disables profiling.`,
  _ = `Epoch`,
  _ = `Batch Start`,
  _ = `Batch End`,
  _ = `Snapshot Keep Duration`,
  _ = `How many days to keep snapshots for. Snapshots older than this will be automatically deleted.  Projects that take a lot of snapshots can keep fewer days and still have enough data for training.  It's generally good to keep this under 30 days.`,
  _ = `Snapshot Keep Duration`,
  _ = `Fetch Keep Count`,
  _ = `How many fetches of training samples to on the backend. Once a fetch has been cycled out, you won't be able to train from it anymore.`,
  _ = `Fetch Keep Count`,
  _ = `Compression`,
  _ = `Should the snapshots be compressed when preprocessed for training? Enabling compression will make the fetch and train slightly slower, but might be useful if the preprocessing could cause large files (eg. large onehots)`,
  _ = `Enable Compression?`,
  _ = `Data Source List`,
  _ = `The list of Data Sources that your project makes use of. Added data sources can further specify how each of their data elements are used by your model.`,
  _ = `No Data Sources current selected for this project.`,
  _ = `Adding Data Sources to Project`,
