  _ = `GENERAL INPUT Support`,
  _ = `In order to best describe your game’s level of controller support to players, we have a quick wizard with a few short questions. Please complete this wizard with answers to the best of your knowledge so that Steam can connect players with games that work well with the devices they have.`,
  _ = `Note that any VR devices, including input devices, that your game supports should be described in the system requirements. Controller support described here should refer to your desktop or Big Picture mode support.`,
  _ = `What kind of devices can be used to comfortably play your game?`,
  _ = `Mouse and keyboard only`,
  _ = `Mouse and keyboard, plus gamepads`,
  _ = `Mouse and keyboard, but gamepad is preferred`,
  _ = `Gamepad Required; No support for mouse and keyboard`,
  _ = `Yes, my game meets the criteria above for full support`,
  _ = `No, my game doesn’t meet all of the above criteria`,
  _ = `DualShock Controller (USB)`,
  _ = `DualShock Controller (USB + Bluetooth)`,
  _ = `DualSense Controller (USB)`,
  _ = `DualSense Controller (USB + Bluetooth)`,
  _ = `No, my game doesn’t support any PlayStation Controllers`,
  _ = `Yes, my game has full Steam Input API integration`,
  _ = `No, my game doesn’t make use of Steam Input API`,
  _ = `Xbox Controller Support`,
  _ = `If your game has full Xbox Controller support, it would be possible for a player to launch, configure, play, and exit your game without access to a keyboard. To truthfully indicate that your game has full Xbox Controller support, your game would need to be able to do the following:`,
  _ = `A player must be able to do everything in the game with only a controller. This includes getting past any pre-game launchers, playing the game, interacting with menus, changing settings, and exiting the game.`,
  _ = `When the controller is disconnected, the game must pause unless it's a multiplayer game.`,
  _ = `Any prompts to enter text must open a virtual keyboard on screen.`,
  _ = `If your game supports local multiplayer, that mode must work with multiple controllers.`,
  _ = `Does your game meet the above criteria for full Xbox Controller support?`,
  _ = `PlayStation Controller Support`,
  _ = `If your game has support for one or more PlayStation Controller models listed below, it should generally be possible to use those devices to do everything in game that can be done with Xbox controllers. In addition, your game must do the following in order to be considered as supporting PlayStation controllers:`,
  _ = `Display the correct glyphs (icons) on screen when prompting the user to press a specific button on the controller.`,
  _ = `Play the game, interact with menus, change settings, exit.`,
  _ = `<1>USB/Bluetooth Note:</1> For PlayStation controllers on PC, it can be quite common for USB connection to work well but not have the same level of support when connected via Bluetooth. Please confirm with your tech team that the game does in fact work with Bluetooth before selecting those below.`,
  _ = `<1>Yes</1>, my game supports: (select all that apply)`,
  _ = `Steam Input API Integration`,
  _ = `If your game has fully integrated with the Steam Input API, then it would work completely with just about any of 200+ models of controller that a player connects, including future models. To truthfully say that your game has this support, it would need to do at least these things:`,
  _ = `Implement Steam Input API actions and query the associated action origin in order to display the right controller glyphs in-game for major controller models.`,
  _ = `Automatically pause if controller is disconnected.`,
  _ = `The player must be able to remap the buttons on the controller they are using through the Steam configurator.`,
  _ = `If you have any doubts, please ask your tech team whether they are using the Steam Input API.`,
  _ = `Does your game make full use of the Steam Input API as described above?`,
  _ = `Controller Support Wizard`,
  _ = `Summary`,
  _ = `Based on what you’ve told us about your controller support, Steam will show the following breakdown for customers:`,
  _ = `Based on what you’ve told us about your controller support, Steam will not show any gamepad devices as supported.`,
