  _ = `Releasing`,
  _ = `Season Pass Roadmap Description`,
  _ = `Season passes are a purchasable item of DLC with a promise of future content to be delivered to those customers, either as separate DLC releases, or as additional content unlocked within the base game.`,
  _ = `To make this commitment, developers must describe each of the major content delivery dates and contents to players by entering each date and content below.`,
  _ = `Use the general 'About This DLC' section above to describe the season pass in general, while using the content delivery dates below to specific individual content releases.`,
  _ = `When you are ready to tell players that you have released content in the season pass, use the 'Mark as Released' option below and follow the instructions. Please review <1>Season Pass Release Documentation</1> for details.`,
