  _ = `Steam Team Industry Meetups Survey`,
  _ = `Hi %1$s,%2$s Where would you like to meet us?`,
  _ = `Listed below are events that members of the Steam Team are considering attending. If you are also considering attendance, or if you live nearby and would be available for meetups, please let us know in the form below. We will use this to better plan our travel and event schedules. If you register for an event that we plan on attending, we will prioritize those who are attending the event before sending our broader invites.`,
  _ = `About You`,
  _ = `Let us know who you are and how best to contact you:`,
  _ = `Email Address`,
  _ = `Address missing`,
  _ = `Update email address?`,
  _ = `This defaults to the email address on file with your partner account. You can update if you wish for event communication to go through a different address.`,
  _ = `Company`,
