  _ = `Yes, I would be comfortable with English as the primary language`,
  _ = `No, I would need translation assistance`,
  _ = `Which language would you prefer?`,
  _ = `This is to help us determine if interpreters would be needed when hosting such an event`,
  _ = `Meet Steam Survey: %1$s`,
  _ = `Do you have any feedback about any of the Steam sessions you attended at Valve's rented space in Convene? This is literally a one-question survey. We’re just looking to understand if something stood out in your mind about content, quality, timing, location, or subject matter of the sessions, good or bad.`,
