  _ = `Required asset missing.`,
  _ = `Startup Movie`,
  _ = `Preview Image`,
  _ = `Video Guidelines`,
  _ = `Startup movies need to be 1920x1200px in size for fullscreen display on Steam Deck. They should be made with consideration for the fact that they will be cropped to 1920x1080px on most displays in Big Picture mode.`,
  _ = `They should be between 3-10 seconds in length.`,
  _ = `May include your game's logo but no other text or marketing material is permitted.`,
  _ = `No transparency is permitted. You may need to disable the alpha channel when exporting.`,
  _ = `Final file needs to be in .webm or .mp4 format and no larger than 50mb. It will be compressed to a reasonable file size.`,
  _ = `Audio Guidelines`,
  _ = `All startup movies contain audio as well as video. Audio should be designed to complement the small Steam Deck speakers output and not too loud that it overwhelms the user on startup.`,
  _ = `Audio files should be in a 16-bit 48kHz format.`,
  _ = `Final output should be -12 dB peak and -14 LUFS average volume. We will normalize audio to ensure audio isn't too loud.`,
  _ = `Avoid too many mid-low frequencies and consider a HPF starting around 40-80Hz.`,
  _ = `Consider adding fades at the start and finish of the audio file to avoid any click or hard cut at the end of the startup video.`,
  _ = `Preview Image Guidelines`,
  _ = `Please provide a 1920x1200px still image from your startup movie. This image will be used to represent your startup movie in a user's inventory.`,
  _ = `jpeg, png and webp are accepted.`,
  _ = `No transparency is permitted.`,
  _ = `No animation is permitted - it must be a single frame image.`,
