  _ = `Testing`,
  _ = `Define and update your game's achievements.`,
  _ = `For best results, achievement icons should be 256x256 pixel PNG images. They can be as small as 64x64, but it is recommended you use the larger size. We recommend that achieved icons be colorful; unachieved icons should be grayscale.`,
  _ = `Since achievements can appear in various places throughout the Steam Community, the names and icons you enter must be appropriate for all ages and audiences. Valve may remove games from the store entirely if their achievements violate <1>community content guidelines</1> or are otherwise offensive.`,
  _ = `To fully enable Achievements, and to complete the release checklist, you also need to select the corresponding tick-box in your store page info under <1>'Supported Features'</1>.`,
